description:
Write three async helpers in a static class `AsyncTools`:

```csharp
public static async Task<int[]> LoadAllAsync(int[] ids, Func<int, Task<int>> load)
public static async Task<string> FirstSuccessfulAsync(params Func<Task<string>>[] sources)
public static async Task<T> WithTimeoutAsync<T>(Task<T> task, TimeSpan timeout)
```

- `LoadAllAsync` starts every load at once and returns the results in the order of `ids`.
- `FirstSuccessfulAsync` tries the sources **one after another** and returns the first result that does not throw. If all fail, it throws an `AggregateException` holding every exception, in order. With no sources it throws `ArgumentException`.
- `WithTimeoutAsync` returns the task's result if it finishes within `timeout`, and otherwise throws a `TimeoutException` (the task may keep running in the background). An exception from the task itself comes through unchanged.

starter.Solution.cs:
public static class AsyncTools
{
    public static async Task<int[]> LoadAllAsync(int[] ids, Func<int, Task<int>> load)
    {
        var results = new List<int>();
        foreach (int id in ids) results.Add(await load(id));
        return results.ToArray();
    }

    public static async Task<string> FirstSuccessfulAsync(params Func<Task<string>>[] sources)
    {
        return await sources[0]();
    }

    public static async Task<T> WithTimeoutAsync<T>(Task<T> task, TimeSpan timeout)
    {
        return await task;
    }
}

solution.Solution.cs:
public static class AsyncTools
{
    public static async Task<int[]> LoadAllAsync(int[] ids, Func<int, Task<int>> load)
    {
        return await Task.WhenAll(ids.Select(load));
    }

    public static async Task<string> FirstSuccessfulAsync(params Func<Task<string>>[] sources)
    {
        if (sources.Length == 0) throw new ArgumentException("no sources", nameof(sources));
        var errors = new List<Exception>();
        foreach (var source in sources)
        {
            try
            {
                return await source();
            }
            catch (Exception e)
            {
                errors.Add(e);
            }
        }
        throw new AggregateException("every source failed", errors);
    }

    public static async Task<T> WithTimeoutAsync<T>(Task<T> task, TimeSpan timeout)
    {
        Task finished = await Task.WhenAny(task, Task.Delay(timeout));
        if (finished != task) throw new TimeoutException($"no result within {timeout.TotalMilliseconds} ms");
        return await task;
    }
}

unitTests:
static T Run<T>(Task<T> task) => task.GetAwaiter().GetResult();

Test("loading at the same time", () =>
{
    int running = 0, peak = 0;
    object gate = new();
    async Task<int> Load(int id)
    {
        int now = Interlocked.Increment(ref running);
        lock (gate) peak = Math.Max(peak, now);
        await Task.Delay(50 - id * 10);
        Interlocked.Decrement(ref running);
        return id * 100;
    }
    CheckEq(Run(AsyncTools.LoadAllAsync([1, 2, 3, 4], Load)), new[] { 100, 200, 300, 400 });
    CheckEq(peak, 4);
    CheckEq(Run(AsyncTools.LoadAllAsync([], Load)).Length, 0);
});

Test("first successful source", () =>
{
    var tried = new List<string>();
    Func<Task<string>> Fails(string name) => async () => { tried.Add(name); await Task.Delay(5); throw new InvalidOperationException(name); };
    Func<Task<string>> Works(string name) => async () => { tried.Add(name); await Task.Delay(5); return name; };
    CheckEq(Run(AsyncTools.FirstSuccessfulAsync(Fails("cache"), Works("disk"), Works("network"))), "disk");
    CheckEq(tried, new[] { "cache", "disk" });
    try
    {
        Run(AsyncTools.FirstSuccessfulAsync(Fails("a"), Fails("b")));
        Check(false, "should throw");
    }
    catch (AggregateException e)
    {
        CheckEq(e.InnerExceptions.Select(x => x.Message), new[] { "a", "b" });
    }
    CheckThrows<ArgumentException>(() => Run(AsyncTools.FirstSuccessfulAsync()));
});

Test("timeouts", () =>
{
    async Task<int> Slow(int ms, int value) { await Task.Delay(ms); return value; }
    CheckEq(Run(AsyncTools.WithTimeoutAsync(Slow(10, 7), TimeSpan.FromMilliseconds(500))), 7);
    CheckThrows<TimeoutException>(() => Run(AsyncTools.WithTimeoutAsync(Slow(1000, 7), TimeSpan.FromMilliseconds(50))));
    async Task<int> Broken() { await Task.Delay(5); throw new FormatException("bad"); }
    CheckThrows<FormatException>(() => Run(AsyncTools.WithTimeoutAsync(Broken(), TimeSpan.FromSeconds(1))));
});

